async function runStream(s) {
  const results = []
  // first stage creates the worktree
  let prev = await agent(`${BASE}\n\n${s.stages[0]}`, { label: `${s.key}:1`, phase: 'Port', schema: REPORT, isolation: 'worktree' })
  results.push(prev)
  if (!prev) return { key: s.key, results }
  const wt = prev.worktree_path
  for (let i = 1; i < s.stages.length; i++) {
    prev = await agent(`${BASE}\n\nWork in the existing worktree ${wt} (branch ${prev.branch}); do NOT create another. Previous stage report: ${JSON.stringify(prev)}\n\n${s.stages[i]}`, { label: `${s.key}:${i + 1}`, phase: i === s.stages.length - 1 && s.key !== 'town' ? 'Compare' : 'Port', schema: REPORT })
    results.push(prev)
    if (!prev) return { key: s.key, results }
  }
  if (s.people) {
    prev = await agent(`${BASE}\n\nWork in the existing worktree ${wt}; do NOT create another. Previous stage report: ${JSON.stringify(prev)}\n\n${s.people}`, { label: `${s.key}:people`, phase: 'People', schema: REPORT })
    results.push(prev)
    if (!prev) return { key: s.key, results }
    prev = await agent(`${BASE}\n\nWork in the existing worktree ${wt}; do NOT create another. Previous stage report: ${JSON.stringify(prev)}\n\n${s.compare}`, { label: `${s.key}:compare`, phase: 'Compare', schema: REPORT })
    results.push(prev)
  }
  return { key: s.key, worktree: wt, results }
}

const streams = await parallel(STREAMS.map(s => () => runStream(s)))
return { streams }

